// Lo unico configurable de este workflow: el mapa de textos de saludo -> anuncio.
//
// Evolution/Baileys solo entrega externalAdReply cuando el usuario responde a un
// anuncio de Estados de WhatsApp (10 de 17.637 mensajes medidos). Los anuncios que
// abren el chat con un texto prellenado no mandan contexto, asi que se identifican
// por ese texto. Clave = como EMPIEZA el primer mensaje (no hace falta el texto
// completo); valor = como quieres ver el anuncio en Chatwoot.
//
// ponytail: startsWith en vez de un match difuso. Un mensaje organico posterior no
// arranca con el saludo exacto del anuncio, asi que no re-etiqueta la conversacion.
const AD_PREFILLS = {
  // '¡Hola! Quiero más información sobre esta butaca': 'Butacas - Ago 2026',
  // '¡Hola! Quiero más información.': 'Genérico - Ago 2026',
};

// externalAdReply cuelga de imageMessage / audioMessage / stickerMessage /
// extendedTextMessage segun el tipo, y Evolution ademas sube el contextInfo al
// nivel de `data`, asi que se busca recursivamente sobre todo `data`.
const find = (obj, key) => {
  if (!obj || typeof obj !== 'object') return null;
  if (obj[key] !== undefined && obj[key] !== null) return obj[key];
  for (const v of Object.values(obj)) {
    const hit = find(v, key);
    if (hit !== null && hit !== undefined) return hit;
  }
  return null;
};

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const data = body.data ?? body;

  const ad = find(data, 'externalAdReply') || {};
  const text = (data.message?.conversation || data.message?.extendedTextMessage?.text || '').trim();
  const prefill = Object.keys(AD_PREFILLS).find((p) => text.startsWith(p));

  // Sin anuncio ni saludo conocido no hay nada que atribuir: la mayoria cae aqui.
  if (!ad.sourceId && !prefill) continue;

  const convId = data.chatwootConversationId;
  if (!convId) {
    // ponytail: si esta rama se llena, Evolution aun no habia creado la
    // conversacion al emitir el webhook -> resolver el id buscando por
    // telefono (GET /contacts/search?q=<numero>) antes del POST.
    out.push({ json: { skip: true, jid: data.key?.remoteJid, ad_id: ad.sourceId } });
    continue;
  }

  // sourceApp dice DONDE corrio el anuncio (whatsapp = Estados, facebook,
  // instagram); entryPointConversionSource solo viene en algunos payloads.
  const src = find(data, 'entryPointConversionSource') || ad.sourceApp || 'whatsapp';
  const adId = ad.sourceId || '';
  const title = ad.title || AD_PREFILLS[prefill] || '';

  out.push({
    json: {
      skip: false,
      // El propio payload trae con que preguntarle a Evolution por su account
      // de Chatwoot, asi que no hay mapa inbox->account que mantener.
      instance: body.instance ?? data.instance,
      apikey: body.apikey,
      server_url: body.server_url,
      conv_id: convId,
      inbox_id: data.chatwootInboxId,
      jid: data.key?.remoteJid,
      // ponytail: URL firmada del CDN de Meta, expira en horas. Sirve para trafico
      // en vivo. Si un backfill viejo falla al descargarla, usar thumb_b64.
      // Vacia cuando la atribucion vino del texto: ahi no hay creativo que bajar y
      // el nodo "Tiene creativo?" corta el flujo despues de guardar los atributos.
      image_url: ad.originalImageUrl || ad.thumbnailUrl || '',
      thumb_b64: ad.thumbnail || '',
      custom_attributes: {
        ad_source: src,
        ad_id: adId,
        ad_title: title,
        ad_copy: (ad.body || text).trim().slice(0, 200),
        ad_url: ad.sourceUrl || ''
      },
      note: [
        '**Lead desde anuncio de Meta**',
        '',
        '- Fuente: ' + src + ' (' + (ad.sourceType || 's/d') + ')',
        '- Anuncio: ' + (title || 's/d'),
        '- Anuncio (id): ' + (adId || 's/d'),
        '- Ads Manager: https://adsmanager.facebook.com/adsmanager/manage/ads?selected_ad_ids=' + adId,
        '- Preview WhatsApp: ' + (ad.sourceUrl || 's/d'),
        '',
        (ad.body || '').trim().slice(0, 300)
      ].join('\n')
    }
  });
}

return out;
